{
  "blocks": [
    {
      "kind": "paragraph",
      "md": "Only the masculine ones change. When *der Bruder* is the object (the thing being acted on), *mein* becomes *meinen*. Feminine, neuter, and plural forms stay the same whether they're subject or object."
    },
    {
      "kind": "list",
      "style": "bullet",
      "items": [
        "*Mein Bruder wohnt in Berlin.* (subject — stays **mein**)",
        "*Ich rufe meinen Bruder an.* (object — becomes **meinen**)",
        "*Meine Schwester kocht.* / *Ich rufe meine Schwester an.* (no change, either role)"
      ]
    },
    {
      "kind": "mcq",
      "id": "check-accusative",
      "prompt": "Ich besuche ___ Vater am Wochenende. (I'm visiting my father this weekend.)",
      "options": [
        { "id": "a", "label": "mein" },
        { "id": "b", "label": "meinen" },
        { "id": "c", "label": "meine" }
      ],
      "correctId": "b",
      "explain": "*Vater* is masculine and here it's the object of *besuche*, so *mein* shifts to *meinen*."
    }
  ]
}
